def _format_dimension(value):
    return "{:g}".format(value)


def _section(model, values):
    section = dict(zip(_FIELDS, map(float, values)))
    section["model"] = model
    section["name"] = "{} [{}x{}x{}x{}]".format(
        model.replace(chr(0x00D7), "x"),
        _format_dimension(section["H"]),
        _format_dimension(section["B"]),
        _format_dimension(section["t1"]),
        _format_dimension(section["t2"]),
    )
    validate_section(section)
    return section


def validate_section(section):
    try:
        h = float(section["H"])
        b = float(section["B"])
        t1 = float(section["t1"])
        t2 = float(section["t2"])
        radius = float(section["r"])
    except (KeyError, TypeError, ValueError):
        raise ValueError("HK section requires H, B, t1, t2 and r.")
    if min(h, b, t1, t2, radius) <= 0.0:
        raise ValueError("HK dimensions must be positive.")
    if h <= 2.0 * t2:
        raise ValueError("HK height must exceed both flange thicknesses.")
    if b <= t1:
        raise ValueError("HK flange width must exceed web thickness.")
    if radius >= min((b - t1) / 2.0, h - 2.0 * t2):
        raise ValueError("HK root radius is too large for the section.")


HK_DATA = OrderedDict(
    (section["name"], section)
    for model, values in _ROWS
    for section in (_section(model, values),)
)
PROFILE_NAMES = tuple(HK_DATA.keys())
DEFAULT_PROFILE = PROFILE_NAMES[0]


def profile_names():
    return PROFILE_NAMES


def get_section(profile_name):
    try:
        return dict(HK_DATA[profile_name])
    except KeyError:
        raise KeyError("Unknown HK profile: {}".format(profile_name))


def nominal_area_mm2(section):
    """Area of the parallel-flange outline with four root fillets."""
    validate_section(section)
    h = float(section["H"])
    b = float(section["B"])
    t1 = float(section["t1"])
    t2 = float(section["t2"])
    radius = float(section["r"])
    corner_factor = 1.0 - math.pi / 4.0
    return 2.0 * b * t2 + (h - 2.0 * t2) * t1 + 4.0 * corner_factor * radius * radius
